"""Spec for count_unprocessed_messages: number of messages from sender_id whose 'processed' flag is False.

Domain: messages is a list of dicts with keys 'id', 'sender_id', 'timestamp', 'processed' (bool);
sender_id is a string that may or may not appear in the list.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "count_unprocessed_messages"

CLARIFICATIONS = [
    "Each message is a dict with keys 'id', 'sender_id', 'timestamp' and 'processed' (a bool that is True once the message has been processed).",
    "Return the count as an int (0 when the sender has no unprocessed messages or the list is empty).",
]

senders = st.sampled_from(["A", "B", "C", "D"])


@st.composite
def message_lists(draw):
    n = draw(st.integers(0, 25))
    flag = st.one_of(st.booleans(), st.just(draw(st.booleans())))
    return [
        {"id": i + 1, "sender_id": draw(senders), "timestamp": 1633072800 + 100 * i + draw(st.integers(0, 50)),
         "processed": draw(flag)}
        for i in range(n)
    ]


def count(messages, sender):
    return len([m for m in messages if m["sender_id"] == sender and m["processed"] is False])


@prop("The result is an int equal to the number of unprocessed messages from the sender.", msgs=message_lists(), sender=senders)
def matches_definition(f, msgs, sender):
    r = f(msgs, sender)
    assert isinstance(r, int) and not isinstance(r, bool)
    assert r == count(msgs, sender)


@prop("Processed messages are never counted.", msgs=message_lists(), sender=senders)
def processed_ignored(f, msgs, sender):
    for m in msgs:
        m["processed"] = True
    assert f(msgs, sender) == 0


@prop("Messages from other senders are never counted.", msgs=message_lists(), sender=senders)
def other_senders_ignored(f, msgs, sender):
    others = [m for m in msgs if m["sender_id"] != sender]
    assert f(others, sender) == 0


@prop("Counts over all senders add up to the total number of unprocessed messages.", msgs=message_lists())
def counts_partition(f, msgs):
    assert sum(f(msgs, s) for s in ["A", "B", "C", "D"]) == sum(1 for m in msgs if not m["processed"])


@prop("Message order does not affect the count.", msgs=message_lists(), sender=senders, data=st.data())
def order_invariant(f, msgs, sender, data):
    shuffled = data.draw(st.permutations(msgs))
    assert f(list(shuffled), sender) == f(msgs, sender)


@prop("An empty message list gives 0.", sender=senders)
def empty_list(f, sender):
    assert f([], sender) == 0

"""Spec for can_make_bouquets: is there a day on which m disjoint bouquets of k adjacent bloomed flowers can be picked?

Domain: flowers is a non-empty list of positive integers (bloom days), k >= 1, m >= 1.
On day d a flower has bloomed iff its bloom day <= d; each flower goes into at most one bouquet.
"""
from hypothesis import strategies as st
from proof_ft.spec_runtime import prop

ENTRY_POINT = "can_make_bouquets"

CLARIFICATIONS = [
    "A flower can be picked on day d once its blooming day is <= d, and each flower can be used in at most one bouquet.",
    "flowers is non-empty and k, m >= 1; return a bool.",
]

days = st.one_of(st.integers(1, 5), st.integers(1, 10**9))


@st.composite
def cases(draw):
    flowers = draw(st.lists(days, min_size=1, max_size=15))
    k = draw(st.integers(1, 6))
    m = draw(st.integers(1, 6))
    return flowers, k, m


def max_bouquets_on(flowers, k, day):
    """Best number of disjoint bouquets: split bloomed flowers into maximal adjacent runs."""
    total, run = 0, 0
    for b in flowers + [day + 1]:
        if b <= day:
            run += 1
        else:
            total += run // k
            run = 0
    return total


def possible(flowers, k, m):
    return any(max_bouquets_on(flowers, k, d) >= m for d in set(flowers))


@prop("The result is a bool telling whether some day allows m bouquets.", case=cases())
def matches_definition(f, case):
    flowers, k, m = case
    r = f(flowers, k, m)
    assert isinstance(r, bool)
    assert r == possible(flowers, k, m)


@prop("If m bouquets are possible then fewer bouquets are possible too.", case=cases())
def monotone_in_m(f, case):
    flowers, k, m = case
    if f(flowers, k, m) and m > 1:
        assert f(flowers, k, m - 1) is True


@prop("Needing more flowers than exist (k * m > len(flowers)) is impossible.", case=cases())
def too_few_flowers(f, case):
    flowers, k, m = case
    m = len(flowers) // k + 1
    assert f(flowers, k, m) is False


@prop("Using exactly all flowers (k * m == len(flowers)) is possible once all have bloomed.",
      flowers=st.lists(days, min_size=1, max_size=15), data=st.data())
def exact_fit(f, flowers, data):
    n = len(flowers)
    k = data.draw(st.sampled_from([d for d in range(1, n + 1) if n % d == 0]))
    assert f(flowers, k, n // k) is True


@prop("Single-flower bouquets are possible iff m <= number of flowers.",
      flowers=st.lists(days, min_size=1, max_size=10), m=st.integers(1, 12))
def single_flower_bouquets(f, flowers, m):
    assert f(flowers, 1, m) is (m <= len(flowers))

reference_solution:
def can_make_bouquets(flowers, k, m):
    """
    Determine if it is possible to make m bouquets each consisting of k consecutive flowers.
    """
    def can_bloom(day):
        count = 0  # to keep track of consecutive blooming flowers
        bouquets = 0  # to keep track of bouquets made
        for bloom_day in flowers:
            if bloom_day <= day:
                count += 1
                if count == k:
                    bouquets += 1
                    count = 0
            else:
                count = 0
            if bouquets >= m:
                return True
        return False

    low, high = min(flowers), max(flowers)
    while low < high:
        mid = (low + high) // 2
        if can_bloom(mid):
            high = mid
        else:
            low = mid + 1

    return can_bloom(low)

